export function solarSpinnerStyle(props: SolarSpinnerProps = {}): Style {
  const p: Record<string, unknown> = { ...solarSpinnerDefaults };
  for (const [k, v] of Object.entries(props)) if (v !== undefined) p[k] = v;
  const key = `variant=${p.variant}`;
  const s = solarSpinnerStyles as unknown as {
    reset: Style;
    root: Style;
    sizes: Record<string, Style>;
    appearances: Record<string, Style>;
    combined: Record<string, Record<string, Style>>;
  };
  const size = p.size as string;
  return merge(
    s.reset,
    s.root,
    s.sizes[size],
    s.appearances[key],
    s.combined[size]?.[key],
  );
}

